import{_ as d,o as r,c as o,a2 as e}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"01 · 心智模型与方法论","description":"","frontmatter":{},"headers":[],"relativePath":"01-心智模型与方法论.md","filePath":"01-心智模型与方法论.md"}'),n={name:"01-心智模型与方法论.md"};function a(i,t,s,h,l,g){return r(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="_01-·-心智模型与方法论" tabindex="-1">01 · 心智模型与方法论</h1><h2 id="_1-三层模型" tabindex="-1">1. 三层模型</h2><table tabindex="0"><thead><tr><th>层</th><th>是什么</th><th>旋钮</th><th>何时进入</th></tr></thead><tbody><tr><td>业务层</td><td>工作流：选哪些组件、怎么连接</td><td>ControlNet 强度、denoise、参考图通道、LoRA 通道</td><td>第 1–4 周</td></tr><tr><td>参数层</td><td>组件上的数值</td><td>CFG、步数、采样器、种子</td><td>第 5 周起</td></tr><tr><td>对比层</td><td>控制变量实验</td><td>每次只变一个</td><td>最后</td></tr></tbody></table><p><strong>关键区分</strong>：ControlNet 强度与 denoise 是<strong>业务层旋钮</strong>（改变工作流行为，值得比较）；步数/CFG/采样器是<strong>参数层旋钮</strong>（渲染细节，默认值即可）。</p><h2 id="_2-控制通道的效力排序-w1-里谁在干活" tabindex="-1">2. 控制通道的效力排序（W1 里谁在干活）</h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ControlNet 线稿强度  &gt;  denoise 幅度  &gt;  负向提示词  &gt;  正向提示词</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>&quot;修正结构&quot;的真实机制：模型先验 + 上述旋钮，<strong>不是提示词在发指令</strong></li><li>提示词是<strong>描述</strong>（画面里有什么），不是指令（帮我改什么）</li><li>标签系模型（NoobAI）里，句子提示词基本无效，必须用标签</li></ul><h2 id="_3-反馈的两种类型-平行基线的划分依据" tabindex="-1">3. 反馈的两种类型（平行基线的划分依据）</h2><table tabindex="0"><thead><tr><th>类型</th><th>机制</th><th>练什么</th><th>代表</th></tr></thead><tbody><tr><td>隐性纠错</td><td>你不指出错误，模型先验沿你的线&quot;顺手修正&quot;，你读差异</td><td>发现盲区（自己没注意到的错）</td><td>W1 贴线重绘</td></tr><tr><td>显性纠错</td><td>你必须先说&quot;哪里错了、怎么错&quot;，模型再改</td><td>诊断眼（改好了=诊断对，改不好=诊断错或模型不行）</td><td>W2/W3 指令修图</td></tr></tbody></table><p>聊天模型讲评已被实测否决：反馈由<strong>修图动作本身</strong>承担，不讲评、直接改给你看。</p><h2 id="_4-两个目标水位线-并存-别互相替代" tabindex="-1">4. 两个目标水位线（并存，别互相替代）</h2><table tabindex="0"><thead><tr><th>水位线</th><th>查什么</th><th>说明</th></tr></thead><tbody><tr><td>平均画师版（W1-B）</td><td>基本功错误（解剖/比例/透视/明暗/线条/构图）</td><td>重绘不加任何风格约束</td></tr><tr><td>老师风格版（W5）</td><td>与特定画师的风格距离</td><td>IP-Adapter（浅）或 LoRA（深）</td></tr></tbody></table><p>目标水位线换成老师后，差异分类多一类：<strong>风格距离</strong>——它是学习目标，不是错误。</p><h2 id="_5-浅拷贝-vs-深拷贝-风格获取的两种模型" tabindex="-1">5. 浅拷贝 vs 深拷贝（风格获取的两种模型）</h2><table tabindex="0"><thead><tr><th></th><th>IP-Adapter / 多参考跟随</th><th>风格 LoRA</th></tr></thead><tbody><tr><td>发生时机</td><td>推理时（零训练，即时生效）</td><td>训练时（一次投入，长期复用）</td></tr><tr><td>复制深度</td><td>表层统计：配色、笔触、渲染质感</td><td>更深：风格分布被烙进模型</td></tr><tr><td>漂移</td><td>单图会漂移，3–5 张多参考才稳</td><td>稳定</td></tr><tr><td>换老师成本</td><td>换参考图即可</td><td>重新训练</td></tr><tr><td>本质比喻</td><td>指着一道菜说&quot;照这个做&quot;</td><td>厨师进修这门菜系</td></tr></tbody></table><p><strong>边界（诚实版）</strong>：两者都抓不住作者的<strong>构造逻辑</strong>（为什么这么构图、怎么理解体积）——&quot;为什么&quot;仍靠你的自评临摹分析，AI 给的是&quot;像&quot;，你学的是&quot;为什么像&quot;。</p><h2 id="_6-组件语义词典" tabindex="-1">6. 组件语义词典</h2><table tabindex="0"><thead><tr><th>组件</th><th>是什么 → 在你的工作流里扮演什么 → 默认 → 何时动</th></tr></thead><tbody><tr><td>底模（NoobAI）</td><td>画师人格 → 决定重绘结果不跑成写实风 → — → 想换画风领域时（换模型=换画师）</td></tr><tr><td>CLIP 文本编码器</td><td>把标签翻译成向量 → 提示词入口 → <strong>无需 clip skip</strong>（官方） → 不动</td></tr><tr><td>VAE</td><td>潜空间↔像素转换器 → img2img 的 Encode/Decode → SDXL 自带 → OOM 时用 tiled VAE</td></tr><tr><td>正向提示词</td><td>描述&quot;画面里有什么&quot; → WD14 自动生成 → 官方前缀+内容标签 → 内容不匹配时微调</td></tr><tr><td>负向提示词</td><td>错误压制通道 → &quot;修正手/解剖&quot;的主要文字通道 → 官方模板（见 03） → 加词观察</td></tr><tr><td>采样器+步数</td><td>噪声→图像的路径规划器 → — → <strong>Euler a / 28 步</strong>（官方） → 第 5 周起</td></tr><tr><td>CFG</td><td>提示词服从强度 → — → <strong>5</strong>（官方区间 3~6） → 过饱和/不听指挥时 ±1</td></tr><tr><td>种子</td><td>随机起点 → 比较时必须固定 → — → 换构图才换</td></tr><tr><td>分辨率</td><td>出图尺寸 → 原画比例就近选档 → 官方列表（见 03） → 低于 512×512 会出错</td></tr><tr><td>ControlNet</td><td>结构通道（管骨架） → 把你的线稿当约束 → 强度 0.8（A）/0.3（B） → 0.3~1.0 都试过再定</td></tr><tr><td>预处理器</td><td>画→引导图翻译器 → LineartAnime 提取线稿 → — → 换引导类型时</td></tr><tr><td>denoise</td><td>改动幅度 → 半贴线重画的甜区 → 0.45（A）/0.65（B） → 0.3~0.7 扫描</td></tr><tr><td>WD14 Tagger</td><td>图→标签 → 自动提示词/训练打标 → — → 标签不准时手动改</td></tr><tr><td>LoRA</td><td>风格/概念补丁 → 老师浓度旋钮（weight） → 0.6~1.0 → 过拟合/欠拟合时调</td></tr><tr><td>IP-Adapter</td><td>零训练风格跟随 → 老师风格即时通道 → weight 0.6~0.9 → 见 05</td></tr></tbody></table><h2 id="_7-多人场景能力边界-画双人-多人互动时" tabindex="-1">7. 多人场景能力边界（画双人/多人互动时）</h2><p>三个能力层，各有各的工具，<strong>纯标签做不到&quot;A 做 X、B 做 Y&quot;</strong>：</p><table tabindex="0"><thead><tr><th>层</th><th>工具</th><th>说明</th></tr></thead><tbody><tr><td>人数</td><td>标签 <code>2girls</code>/<code>3girls</code></td><td>NoobAI 原生支持（Danbooru 语料）；WD14 自动打</td></tr><tr><td>各自动作</td><td><strong>OpenPose ControlNet 多骨架</strong>（Chenkin 含 OpenPose 模式；DWPose 预处理器提取多人骨架）</td><td>&quot;谁做什么&quot;的结构层：每角色一根骨架；骨架可自己摆、可从参考图/自己的画提取</td></tr><tr><td>各自身份</td><td>角色标签/LoRA + <strong>区域条件</strong>（ComfyUI area/region conditioning：mask 分区域各挂 LoRA 与提示词）</td><td>⚠️ 特征串扰是真实问题（LoRA 互相污染）→ 区域 mask + 权重调低 + 角色特征差异拉大</td></tr><tr><td>语义指代（事后修改）</td><td>W3 指令编辑（Qwen-Image-Edit 系列以多角色一致性编辑为主打）</td><td>&quot;把左边女孩的头发改蓝&quot;式指代；云端/租卡</td></tr></tbody></table><p>边界：标签是全局描述；互动&quot;自然感&quot;是模型统计弱点（摆拍感）——<strong>这正是你的建构空间</strong>：AI 给互动结构的普遍性，你负责情境与自然感的集中性（对应 §1.5 的哲学分工）。双人图同样跑 AI 反馈闭环，差异自读&quot;构图&quot;类多一个维度：<strong>互动关系</strong>（视线、距离、接触点、重心）。</p><h2 id="_8-防坑清单" tabindex="-1">8. 防坑清单</h2><ol><li>自评永远在前（顺序反了就是抄作业）</li><li>区分&quot;错误&quot;和&quot;风格差异&quot;（AI 会正常化你的个人笔触，那不是你的失败）</li><li>ControlNet 强度是旋钮不是开关</li><li>工作流 B（平均画师版）不要加&quot;保持我的风格&quot;</li><li>比较时固定种子</li><li>OOM 三板斧：降分辨率（768）+ Hires fix / tiled VAE / 少加载</li></ol>',24)])])}const p=d(n,[["render",a]]);export{u as __pageData,p as default};
